#!/usr/bin/env bash
set -euo pipefail

function download_all {
  C_FILES=(src/libstc.c)
  OTHER_PATHS=(LICENSE include)
  INC_DIRS=(include)
  # Latest commit as of Jan 25 2024, should switch to the next release when the one after 4.2 comes out
  download_repo stc 09790f024ad29fca6fe60528461eeb589d4a917b "https://github.com/stclib/STC.git"

  # Used by the diffapp frontend
  download_javascript diff 5.2.0 dist/diff.js LICENSE
}

NORMAL="\x1b[0m"
EOL="${NORMAL}\n"
BLUE="\x1b[34m"
PINK="\x1b[35m"
GREEN="\x1b[32m"
RED="\x1b[31m"
ERROR=0
SUBDIRS=()

function download_repo {
  local NAME="$1"
  local GIT_TAG="$2"
  local GIT_URL="$3"
  SUBDIRS+=("$NAME")
  rm -rf "./$NAME" "./$NAME-tmp"
  printf "${BLUE}Cloning %s files/dirs from %s...$EOL" "$((${#C_FILES[@]} + ${#OTHER_PATHS[@]}))" "$GIT_URL"
  if ! git clone --quiet --no-checkout --filter=blob:none "$GIT_URL" "./$NAME-tmp"; then
    printf "${RED}git clone of %s failed$EOL" "$GIT_URL"
    ERROR=1
    return
  fi
  git -C "./$NAME-tmp" sparse-checkout init --cone
  git -C "./$NAME-tmp" sparse-checkout set "${C_FILES[@]}" "${OTHER_PATHS[@]}"
  if ! git -C "./$NAME-tmp" checkout --quiet "$GIT_TAG"; then
    printf "${RED}git checkout of %s failed$EOL" "$GIT_URL"
    ERROR=1
    return
  fi
  mkdir "./$NAME"
  for FILE in "${C_FILES[@]}" "${OTHER_PATHS[@]}"; do
    if test -e "./$NAME-tmp/$FILE"; then
      mkdir -p "$(dirname "./$NAME/$FILE")"
      mv "./$NAME-tmp/$FILE" "./$NAME/$FILE"
    else
      printf "${RED}expected file %s, does not exist$EOL" "$NAME/$FILE"
      ERROR=1
    fi
  done
  rm -rf "./$NAME-tmp"
  local MESON_BUILD="./$NAME/meson.build"
  printf "${BLUE}Writing %s...$EOL" "$MESON_BUILD"
  echo "# AUTOGENERATED by refresh.sh" >>"$MESON_BUILD"
  echo "${NAME}_inc = include_directories(" >>"$MESON_BUILD"
  for INC_DIR in "${INC_DIRS[@]}"; do
    echo "    '$INC_DIR'," >>"$MESON_BUILD"
  done
  echo ")" >>"$MESON_BUILD"
  echo "${NAME}_lib = static_library(" >>"$MESON_BUILD"
  echo "    '$NAME'," >>"$MESON_BUILD"
  echo "    files(" >>"$MESON_BUILD"
  for FILE in "${C_FILES[@]}"; do
    echo "        '$FILE'," >>"$MESON_BUILD"
  done
  echo "    )," >>"$MESON_BUILD"
  echo "    include_directories: [" >>"$MESON_BUILD"
  echo "        ${NAME}_inc," >>"$MESON_BUILD"
  echo "        include_directories('..')," >>"$MESON_BUILD"
  echo "    ]," >>"$MESON_BUILD"
  if test ! -z "${MESON_LIB_ARGS:-}"; then
    echo "    $MESON_LIB_ARGS," >>"$MESON_BUILD"
  fi
  echo ")" >>"$MESON_BUILD"
  unset C_FILES
  unset OTHER_PATHS
  unset INC_DIRS
  unset MESON_LIB_ARGS
}

function download_javascript {
  local PACKAGE="$1"
  local VERSION="$2"
  local CODE_PATH="$3"
  local LICENSE_PATH="$4"
  printf "${BLUE}Downloading ${PACKAGE} v${VERSION} from unpkg...$EOL"
  wget "https://unpkg.com/${PACKAGE}@${VERSION}/${CODE_PATH}" -O "javascript/${PACKAGE}.js"
  wget "https://unpkg.com/${PACKAGE}@${VERSION}/${LICENSE_PATH}" -O "javascript/LICENSE-${PACKAGE}"
}

function copy_in_tsc_libs {
  printf "${BLUE}Ensuring tsc is cloned into test directory...$EOL"
  ../test/clone_typescript_if_needed.sh
  printf "${BLUE}Copying tsc libs from test directory...$EOL"
  rm -rf lib
  cp -r ../test/TypeScript/src/lib lib
  cp -r ../test/TypeScript/LICENSE.txt lib
  cat lib/libs.json \
    | grep -Pv '\w*//' \
    | jq -c '.paths | to_entries[]' | \
  while read MOVE; do
    SRC="lib/$(jq -r .key <<<"$MOVE").d.ts"
    DST="lib/$(jq -r .value <<<"$MOVE" | sed 's/^lib.//')"
    mv "$SRC" "$DST"
  done
  mv 'lib/d.ts' 'lib/default.d.ts'
  printf '/// <reference lib="es2016" />\n' >lib/es7.d.ts # Why???
  TSC_COMMIT="$(git -C ../test/TypeScript rev-parse HEAD)"
  echo "These libraries come from upstream TypeScript at commit $TSC_COMMIT" >lib/README.txt
}

function write_meson_build {
  printf "${BLUE}Writing meson.build for %s thirdparty libraries...$EOL" "${#SUBDIRS[@]}"
  local MESON_BUILD="./meson.build"
  rm -rf "$MESON_BUILD"
  echo "# AUTOGENERATED by refresh.sh" >>"$MESON_BUILD"
  for SUBDIR in "${SUBDIRS[@]}"; do
    echo "subdir('$SUBDIR')" >>"$MESON_BUILD"
  done
  echo "thirdparty_inc = [" >>"$MESON_BUILD"
  for SUBDIR in "${SUBDIRS[@]}"; do
    echo "    ${SUBDIR}_inc," >>"$MESON_BUILD"
  done
  echo "]" >>"$MESON_BUILD"
  echo "thirdparty_libs = [" >>"$MESON_BUILD"
  for SUBDIR in "${SUBDIRS[@]}"; do
    echo "    ${SUBDIR}_lib," >>"$MESON_BUILD"
  done
  echo "]" >>"$MESON_BUILD"
}

function apply_patches {
  for PATCH_FILE in $(ls *patch.txt); do
    printf "${BLUE}Applying %s...$EOL" "$PATCH_FILE"
    cat "$PATCH_FILE" | patch -p0
  done
}

# Change directory to the directory of this script
cd "$( dirname "${BASH_SOURCE[0]}")"
printf "${BLUE}Downloading thirdparty libraries into %s...$EOL" "$PWD"

rm -rf javascript && mkdir -p javascript

download_all
copy_in_tsc_libs
write_meson_build
apply_patches

if test $ERROR == 0; then
  printf "${GREEN}Done$EOL"
else
  printf "${RED}Completed with errors$EOL"
fi
exit $ERROR
